from lib.money import apply_rate
from lib.rates import TAX_PCT, MEMBER_PCT


def total(items, member=False):
    """Cents due for `items`, a list of (unit_price_cents, qty) pairs."""
    subtotal = sum(price * qty for price, qty in items)
    if member:
        subtotal -= apply_rate(subtotal, MEMBER_PCT)
    return subtotal + apply_rate(subtotal, TAX_PCT)
